using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side shipment service with in-memory seed data.
/// Replace with EF Core implementation for production.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments = GenerateSeedData();

    private static List<Shipment> GenerateSeedData() =>
    [
        new()
        {
            Id = 1, TrackingNumber = "SHP-20260701-001",
            Origin = "New York, USA", Destination = "London, UK",
            Status = ShipmentStatus.InTransit,
            ShippedDate = new DateTime(2026, 7, 1),
            EstimatedDelivery = new DateTime(2026, 7, 10),
            CustomerEmail = "alice@example.com",
            Description = "Electronics - 2 pallets"
        },
        new()
        {
            Id = 2, TrackingNumber = "SHP-20260702-002",
            Origin = "Shanghai, China", Destination = "Los Angeles, USA",
            Status = ShipmentStatus.PickedUp,
            ShippedDate = new DateTime(2026, 7, 2),
            EstimatedDelivery = new DateTime(2026, 7, 15),
            CustomerEmail = "bob@example.com",
            Description = "Furniture - 1 container"
        },
        new()
        {
            Id = 3, TrackingNumber = "SHP-20260628-003",
            Origin = "Berlin, Germany", Destination = "Tokyo, Japan",
            Status = ShipmentStatus.OutForDelivery,
            ShippedDate = new DateTime(2026, 6, 28),
            EstimatedDelivery = new DateTime(2026, 7, 8),
            CustomerEmail = "carol@example.com",
            Description = "Automotive parts - 5 crates"
        },
        new()
        {
            Id = 4, TrackingNumber = "SHP-20260625-004",
            Origin = "São Paulo, Brazil", Destination = "Miami, USA",
            Status = ShipmentStatus.Delivered,
            ShippedDate = new DateTime(2026, 6, 25),
            EstimatedDelivery = new DateTime(2026, 7, 3),
            CustomerEmail = "dave@example.com",
            Description = "Coffee beans - 10 bags"
        },
        new()
        {
            Id = 5, TrackingNumber = "SHP-20260703-005",
            Origin = "Sydney, Australia", Destination = "Singapore",
            Status = ShipmentStatus.Delayed,
            ShippedDate = new DateTime(2026, 7, 3),
            EstimatedDelivery = new DateTime(2026, 7, 12),
            CustomerEmail = "eve@example.com",
            Description = "Perishable goods - refrigerated"
        },
        new()
        {
            Id = 6, TrackingNumber = "SHP-20260704-006",
            Origin = "Mumbai, India", Destination = "Dubai, UAE",
            Status = ShipmentStatus.Pending,
            ShippedDate = new DateTime(2026, 7, 4),
            EstimatedDelivery = new DateTime(2026, 7, 9),
            CustomerEmail = "frank@example.com",
            Description = "Textiles - 3 pallets"
        }
    ];

    private static int _nextId = 7;

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_shipments)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (_shipments)
        {
            var shipment = _shipments.FirstOrDefault(
                s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (_shipments)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id)
                ?? throw new KeyNotFoundException($"Shipment {id} not found");
            shipment.Status = newStatus;
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        lock (_shipments)
        {
            shipment.Id = _nextId++;
            _shipments.Add(shipment);
            return Task.FromResult(shipment);
        }
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        // Allow anonymous tracking lookup for customers
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        }).AllowAnonymous();

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("/{id}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, newStatus);
            return Results.Ok(updated);
        });
    }
}

