@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260701-001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Search
            </button>
        </div>
    </div>
</div>

@if (searchPerformed)
{
    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></dd>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                <strong class="text-primary">@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                                @if (shipment.Status == ShipmentStatus.Delayed)
                                {
                                    <br /><small class="text-warning">⚠️ This shipment is delayed. Delivery date may change.</small>
                                }
                                else if (shipment.Status == ShipmentStatus.Delivered)
                                {
                                    <br /><small class="text-success">✅ Delivered</small>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">
            No shipment found with tracking number "<strong>@searchedNumber</strong>". Please check and try again.
        </div>
    }
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searchPerformed;
    private bool isLoading;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isLoading = true;
        searchedNumber = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            searchPerformed = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatch"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="d-flex justify-content-between align-items-center mb-3">
    <div class="input-group" style="max-width: 350px;">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(filterText))
        {
            <button class="btn btn-outline-secondary" @onclick="() => filterText = string.Empty">✕</button>
        }
    </div>
    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (isLoading)
{
    <div class="text-center py-4">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Description</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Description</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@s.Status"
                                    @onchange="e => UpdateStatus(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter.</div>
    }
}

@if (showCreateForm)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Create New Shipment</h5>
                    <button type="button" class="btn-close" @onclick="() => showCreateForm = false"></button>
                </div>
                <div class="modal-body">
                    <div class="mb-3">
                        <label class="form-label">Tracking Number</label>
                        <input type="text" class="form-control" @bind="newShipment.TrackingNumber" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="row mb-3">
                        <div class="col">
                            <label class="form-label">Origin</label>
                            <input type="text" class="form-control" @bind="newShipment.Origin" />
                        </div>
                        <div class="col">
                            <label class="form-label">Destination</label>
                            <input type="text" class="form-control" @bind="newShipment.Destination" />
                        </div>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="row mb-3">
                        <div class="col">
                            <label class="form-label">Shipped Date</label>
                            <input type="date" class="form-control" @bind="newShipment.ShippedDate" />
                        </div>
                        <div class="col">
                            <label class="form-label">Estimated Delivery</label>
                            <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                        </div>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                    <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isSaving">
                        @if (isSaving)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Create
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<Shipment> shipments = [];
    private string filterText = string.Empty;
    private bool isLoading = true;
    private bool showCreateForm;
    private bool isSaving;
    private Shipment newShipment = new();

    private IEnumerable<Shipment> FilteredShipments => string.IsNullOrWhiteSpace(filterText)
        ? shipments
        : shipments.Where(s => s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = updated.Status;
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment
        {
            TrackingNumber = $"SHP-{DateTime.Now:yyyyMMdd}-{Random.Shared.Next(100, 999):000}",
            ShippedDate = DateTime.Today,
            EstimatedDelivery = DateTime.Today.AddDays(7)
        };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        isSaving = true;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments.Add(created);
            showCreateForm = false;
        }
        finally
        {
            isSaving = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

